from __future__ import annotations

import sys

import torch
import helion
import helion.language as hl

from loom import LoomKernel
from loom.loom_utils.kernel_size import resolve_kernel_shape_args
from helion_mlir.custom_op import broadcast  # noqa: F401  (registers the op)


def _k3_gemm(lhs: torch.Tensor, w0: torch.Tensor, w1: torch.Tensor) -> tuple[torch.Tensor, ...]:
    t, k = lhs.size()
    _, n = w0.size()
    out_mul_10 = torch.empty([t, n], dtype=torch.float16, device=lhs.device)
    for tile_t, tile_n in hl.tile([t, n]):
        acc_matmul_66 = hl.zeros([tile_t, tile_n], dtype=torch.float16)
        acc_matmul_70 = hl.zeros([tile_t, tile_n], dtype=torch.float16)
        ss = hl.zeros([tile_t, 32], dtype=torch.float16)
        for tile_k in hl.tile(k):
            xt = lhs[tile_t, tile_k]
            acc_matmul_66 = hl.dot(xt, w0[tile_k, tile_n], acc=acc_matmul_66)
            acc_matmul_70 = hl.dot(xt, w1[tile_k, tile_n], acc=acc_matmul_70)
            half = hl.full([tile_t, tile_k], 0.5, dtype=torch.float16)
            sq = xt * (xt * half)
            ones = hl.full([tile_k, 32], 1.0, dtype=torch.float16)
            ss = hl.dot(sq, ones, acc=ss)
        ss_col = torch.amax(ss, -1, keepdim=True)
        c_1 = hl.full([tile_t, 1], 2.0, dtype=torch.float16)
        sumsq = ss_col * c_1
        c_3 = hl.full([tile_t, 1], 0.00390625, dtype=torch.float16)
        mul_62__col_2 = sumsq * c_3
        c_5 = hl.full([tile_t, 1], 0.01, dtype=torch.float16)
        c_6 = hl.full([tile_t, 1], 0.001, dtype=torch.float16)
        c_7 = c_5 * c_6
        add_63__col_4 = mul_62__col_2 + c_7
        c_9 = hl.full([tile_t, 1], -0.5, dtype=torch.float16)
        powf_64__col_8 = torch.pow(add_63__col_4, c_9)
        broadcast_67_10 = broadcast(powf_64__col_8, 1, [powf_64__col_8.size(0), tile_n])
        mul_68_11 = acc_matmul_66 * broadcast_67_10
        c_13 = hl.full([tile_t, tile_n], -1.0, dtype=torch.float16)
        mul_73_12 = mul_68_11 * c_13
        exp_74_14 = torch.exp(mul_73_12)
        c_16 = hl.full([tile_t, tile_n], 1.0, dtype=torch.float16)
        add_75_15 = exp_74_14 + c_16
        sigmoid_17 = c_16 / add_75_15
        mul_9_18 = mul_68_11 * sigmoid_17
        broadcast_71_19 = broadcast(powf_64__col_8, 1, [powf_64__col_8.size(0), tile_n])
        mul_72_20 = acc_matmul_70 * broadcast_71_19
        mul_10_21 = mul_9_18 * mul_72_20
        out_mul_10[tile_t, tile_n] = mul_10_21
    return out_mul_10,


